intptr_t INCREMENT = 4096;
void *old_break;
void *new_block;

// Get current break location
old_break = sbrk(0);

// Allocate memory: increase the program break
new_block = sbrk(INCREMENT);

if (new_block == (void *)-1) {
    /* Handle ENOMEM error */
    return;
}

// 'new_block' is the start of the newly allocated region

// Deallocate (optional: decrease the break)
sbrk(-INCREMENT);
